/* Local seasons reuse city encounters, branches and combat; no independent reward loop. */
const SEASON_EPOCH=Date.parse('2026-10-24T00:00:00+08:00'),SEASON_DAYS=28;
const SEASON_ROUTES={signal:{n:'霓虹載波',tag:'追逐',mods:['fast'],col:'#8db7ef'},memory:{n:'沉眠備份',tag:'續戰',mods:['tough'],col:'#b3a4d3'},power:{n:'過載心跳',tag:'爆發',mods:['deadly'],col:'#ed967d'}};
const SEASON_PACTS={steady:{n:'穩定頻道',d:'區域固有干擾，通關取得1格充能。',mods:[],gain:1},surge:{n:'失真加壓',d:'增加敵群與精英，通關取得2格充能；每次額外25%生命與15%傷害。',mods:['more','elite'],gain:2}};
const SEASON_MILESTONES=[{id:'first',n:'接回第一條訊號',d:'完成任意1次巡迴',need:1,parts:40,chips:30},{id:'trio',n:'三頻同步',d:'三條頻段均完成一次',need:3,parts:80,chips:60},{id:'midnight',n:'午夜播送',d:'擊破午夜中樞一次',need:1,parts:120,chips:100}];
function seasonCycle(now=Date.now()){return Math.max(0,Math.min(1e4,Math.floor((now-SEASON_EPOCH)/(864e5*SEASON_DAYS))))}
function newSeason(cycle=seasonCycle()){return {cycle,charge:{signal:0,memory:0,power:0},clears:{signal:0,memory:0,power:0},wins:0,claimed:[],history:[]}}
function seasonClean(raw){const n=(v,max=1e6)=>Number.isFinite(v)?Math.max(0,Math.min(max,Math.floor(v))):0,s=newSeason(n(raw?.cycle,1e4));for(const id of Object.keys(SEASON_ROUTES)){s.charge[id]=n(raw?.charge?.[id],6);s.clears[id]=n(raw?.clears?.[id]);}s.wins=n(raw?.wins);s.claimed=[...new Set((Array.isArray(raw?.claimed)?raw.claimed:[]).filter(id=>SEASON_MILESTONES.some(m=>m.id===id)))];s.history=(Array.isArray(raw?.history)?raw.history:[]).filter(x=>x&&Number.isSafeInteger(x.cycle)&&x.cycle>=0).slice(-3).map(x=>({cycle:n(x.cycle,1e4),wins:n(x.wins),clears:n(x.clears)}));return s;}
function seasonEnsure(){G.season=G.season||newSeason();const current=seasonCycle();if(G.season.cycle!==current){const prev=G.season,next=newSeason(current);next.history=[...prev.history,{cycle:prev.cycle,wins:prev.wins,clears:Object.values(prev.clears).reduce((a,b)=>a+b,0)}].slice(-3);G.season=next;G.dirty=true;}return G.season;}
function seasonRunValid(c){const s=c?.season;return !s||s&&Number.isInteger(s.cycle)&&s.cycle>=0&&s.cycle<=1e4&&['contract','finale'].includes(s.mode)&&Object.hasOwn(SEASON_PACTS,s.pact)&&Object.hasOwn(SEASON_ROUTES,c.route);}
function seasonStart(route,pact='steady',finale=false){
 const s=seasonEnsure();if(!SEASON_ROUTES[route]||!SEASON_PACTS[pact]||!cityCanStart(route,1,false))return false;if(finale&&!Object.values(s.charge).every(n=>n>=1))return false;
 if(!cityStart(route,1,false))return false;const c=G.run.city;c.season={cycle:s.cycle,pact,mode:finale?'finale':'contract'};G.run.map.mods=[...new Set([...SEASON_ROUTES[route].mods,...SEASON_PACTS[pact].mods,...(finale?['fast','deadly','tough']:[])])];G.run.map.id='season-'+s.cycle+'-'+Date.now();if(finale){for(const id of Object.keys(SEASON_ROUTES))s.charge[id]--;G.run.map.biome=14;G.run.map.lvl+=3;}G.dirty=true;saveGame();return true;
}
function seasonFinish(c,success){if(!c?.season||!success)return;const s=seasonEnsure();if(c.season.cycle!==s.cycle){logLine('上期巡迴已結束，城市獎勵照常結算。','#475778');return;}if(c.season.mode==='finale'){s.wins++;activityEarn('season');G.parts+=25;logLine('午夜中樞已復原：25零件，巡迴紀錄已更新。','#80cebd');}else{s.clears[c.route]++;s.charge[c.route]=Math.min(6,s.charge[c.route]+SEASON_PACTS[c.season.pact].gain);}G.dirty=true;}
function seasonMilestoneReady(id){const s=seasonEnsure();return id==='first'?Object.values(s.clears).some(n=>n>0):id==='trio'?Object.values(s.clears).every(n=>n>0):id==='midnight'&&s.wins>0;}
function seasonClaim(id,cycle){const s=seasonEnsure(),m=SEASON_MILESTONES.find(m=>m.id===id);if(s.cycle!==cycle||!m||s.claimed.includes(id)||!seasonMilestoneReady(id))return false;s.claimed.push(id);G.parts+=m.parts;G.chips+=m.chips;G.dirty=true;return true;}
function seasonMonster(m,c){if(!c?.season)return;const hard=c.season.pact==='surge',final=c.season.mode==='finale';m.hp*= (hard?1.25:1)*(final?1.4:1);m.hpMax=m.hp;m.dmg*=(hard?1.15:1)*(final?1.2:1);if(final&&m.boss){m.skillCd=.8;m.seasonPulse=5;}}
function seasonMonsterTick(m,dt){if(!G.run?.city?.season||!m.boss||m.dead)return;const c=G.run.city;if(c.season.mode!=='finale')return;m.seasonPulse=(m.seasonPulse??5)-dt;if(m.seasonPulse<=0&&!m.warning){m.seasonPulse=6;const angle=(m.cityPhase||0)*Math.PI*.65,points=Array.from({length:3},(_,i)=>terrainProject(G.h.x+Math.cos(angle+i*2.094)*10,G.h.y+Math.sin(angle+i*2.094)*10));m.warning={skill:'salvo',shape:'circles',x:G.h.x,y:G.h.y,x2:G.h.x,y2:G.h.y,points,radius:8,t:1.3,duration:1.3};addFx({k:'ring',x:m.x,y:m.y,t:0,dur:.5,col:'#b3a4d3'});}}
/* Tower rewards commit once before a short, skippable visual journey. */
function towerStairPosition(){return terrainProject(HX+38,HY-34)}
function towerStairFoot(top=false){const p=towerStairPosition(),z=top?-8:8;return [p[0]+Math.sin(-.4)*z,p[1]+Math.cos(-.4)*z]}
function prepareTowerStair(s){const goal=terrainProject(...towerStairFoot()),points=[terrainProject(s.x,s.y)];let [x,y]=points[0];for(let i=0;i<256&&Math.hypot(goal[0]-x,goal[1]-y)>.1;i++){const q=terrainWaypoint(x,y,...goal);if(Math.hypot(q[0]-x,q[1]-y)<.01)break;points.push(q);[x,y]=q;}s.path=points;s.length=points.slice(1).reduce((sum,p,i)=>sum+Math.hypot(p[0]-points[i][0],p[1]-points[i][1]),0);s.walkTime=s.length/32;s.reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;s.duration=s.reduced?.7:Math.max(3.4,s.walkTime+2.1);return s;}
function towerStairTick(dt,skip=false){const R=G.run,s=R?.stair;if(!R?.tower||!s)return false;if(!s.path)prepareTowerStair(s);deathVisualTick(dt);if(skip||G.offline)s.age=s.duration;else{s.age=Math.min(s.duration,s.age+dt);G.time+=dt;}let target;if(s.reduced){target=[s.x,s.y];G.h.stairLift=0;}else if(s.age<s.walkTime){let distance=s.age*32;target=s.path.at(-1);for(let i=1;i<s.path.length;i++){const a=s.path[i-1],b=s.path[i],d=Math.hypot(b[0]-a[0],b[1]-a[1]);if(distance<=d){target=[a[0]+(b[0]-a[0])*distance/d,a[1]+(b[1]-a[1])*distance/d];break;}distance-=d;}G.h.stairLift=0;}else{const u=Math.min(1,(s.age-s.walkTime)/Math.max(.1,s.duration-s.walkTime)),a=towerStairFoot(),b=towerStairFoot(true);target=[a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u];G.h.stairLift=2+u*15;}G.h.vx=target[0]-G.h.x;G.h.vy=target[1]-G.h.y;G.h.mv=s.reduced?0:12;[G.h.x,G.h.y]=target;G.h.drama=s.reduced?null:{kind:'climb',start:G.time-s.age,duration:s.duration};collectNearby(Math.min(dt,s.duration));if(s.age>=s.duration){delete R.stair;towerCommitFloor();G.h.x=HX;G.h.y=HY;G.h.mv=0;G.h.vx=G.h.vy=0;G.h.stairLift=0;G.h.drama={kind:'rise',start:G.time,duration:.5};}return true;}
function cleanTowerStair(R){G.h.stairLift=0;if(!R?.tower||!R.stair)return;const s=R.stair;if(!Number.isInteger(R.floor)||R.floor<1||s.from!==R.floor||s.paid!==true){delete R.stair;R.kills=0;R.bossOut=false;return;}R.stair=prepareTowerStair({from:R.floor,paid:true,age:0,x:Number.isFinite(s.x)?s.x:HX,y:Number.isFinite(s.y)?s.y:HY});}

