/* Ailments use the same incoming-damage and death owners as direct attacks. */
const HERO_AILMENT_TYPES={wisp:'freeze',shard:'freeze',bomb:'burn',furnace:'burn',spider:'poison',cable:'poison'};
function clearHeroAilments(){G.h.ailments={freeze:0,immuneUntil:0,burn:null,poison:[]};G.h.ailmentGate={};}
function applyHeroAilment(kind,damage,source){if(!['freeze','burn','poison'].includes(kind)||G.h.dead>0||G.h.hp<=0||!Number.isFinite(damage)||damage<=0)return false;const h=G.h,a=h.ailments||(h.ailments={freeze:0,immuneUntil:0,burn:null,poison:[]});h.ailmentGate||={};if(G.time-(h.ailmentGate[kind]??-99)<.7)return false;if(kind==='freeze'&&G.time<(a.immuneUntil||0))return false;h.ailmentGate[kind]=G.time;if(kind==='freeze'){a.freeze=1.2;a.immuneUntil=G.time+4.2;h.castT=h.swingT=-1;}else{const dps=Math.min(G.st.life*(kind==='burn'?.025:.01),damage*(kind==='burn'?.15:.08)),entry={remaining:3,clock:0,dps,source:String(source).slice(0,80)};if(kind==='burn'){if(a.burn)entry.dps=Math.max(entry.dps,a.burn.dps);a.burn=entry;}else{a.poison.push(entry);a.poison=a.poison.sort((x,y)=>y.dps-x.dps).slice(0,3);}}G.dirty=true;return true;}
function heroStatusHit(m,damage,skill=false){const kind=HERO_AILMENT_TYPES[m.type];if(!kind||kind==='freeze'&&!skill)return;applyHeroAilment(kind,damage,monsterLabel(m.type)+'・'+({freeze:'冰凍',burn:'點燃',poison:'中毒'}[kind]));}
function heroFrozen(){return (G.h.ailments?.freeze||0)>0;}
function heroAilmentTick(dt){const a=G.h.ailments;if(!a||G.h.dead>0)return;a.freeze=Math.max(0,(a.freeze||0)-dt);const tick=(entry,label)=>{if(!entry)return;const elapsed=Math.min(dt,entry.remaining);entry.remaining=Math.max(0,entry.remaining-dt);entry.clock+=elapsed;while(entry.clock>=.5-1e-9){entry.clock-=.5;heroDamage(entry.dps*.5,entry.source||label,label);if(G.h.hp<=0)break;}};tick(a.burn,'點燃');if(G.h.hp>0)for(const p of a.poison||[]){tick(p,'中毒');if(G.h.hp<=0)break;}if(a.burn?.remaining<=0)a.burn=null;a.poison=(a.poison||[]).filter(p=>p.remaining>0);}
function applyMonsterPoison(m,dps,source='中毒'){if(!m||m.dead||!(dps>0))return;m.poisons=(m.poisons||[]).filter(p=>p.remaining>0);m.poisons.push({dps,remaining:3,clock:0,source});m.poisons.sort((a,b)=>b.dps-a.dps);m.poisons=m.poisons.slice(0,3);}
function monsterPoisonTick(m,dt){if(!m.poisons?.length)return;for(const p of m.poisons){const elapsed=Math.min(dt,p.remaining);p.remaining=Math.max(0,p.remaining-dt);p.clock+=elapsed;while(p.clock>=.5-1e-9&&!m.dead){p.clock-=.5;hitMon(m,p.dps*.5,false,'中毒');}}m.poisons=m.poisons.filter(p=>p.remaining>0);}

