/* Signal breach encounter: touch, expand, contain, collect. Rewards use ground loot. */
function riftState(){return G.rift||(G.rift={shards:0,clears:0,serial:0,next:30,encounter:null})}
function riftClean(o){const n=v=>Number.isFinite(v)?Math.max(0,Math.min(1e7,Math.floor(v))):0;return{shards:n(o?.shards),clears:n(o?.clears),serial:n(o?.serial),next:Math.max(10,Math.min(120,Number(o?.next)||30)),encounter:riftCleanEncounter(o?.encounter)}}
function riftCleanEncounter(e){if(!e||!['dormant','expand','contain','complete','failed'].includes(e.phase)||!Number.isFinite(e.x)||!Number.isFinite(e.y)||!Number.isInteger(e.id)||typeof e.key!=='string')return null;return{id:Math.max(0,e.id),key:e.key.slice(0,160),x:e.x,y:e.y,phase:e.phase,age:Math.max(0,Math.min(60,+e.age||0)),kills:Math.max(0,Math.min(48,Math.floor(e.kills)||0)),made:Math.max(0,Math.min(48,Math.floor(e.made)||0)),resume:Math.min(12,Math.max(0,(Math.floor(e.made)||0)-(Math.floor(e.kills)||0))),spawn:1,radius:Math.max(8,Math.min(40,+e.radius||8)),paid:e.paid===true,track:e.phase==='dormant'};}
function riftSpawn(){if(G.run||G.train||G.offline||G.h.dead>0||G.depth<4||G.mons.some(m=>m.boss&&!m.dead)||riftState().encounter)return false;const p=terrainProject(G.h.x+28,G.h.y+8),s=riftState();s.encounter={id:++s.serial,key:terrainKey(),x:p[0],y:p[1],phase:'dormant',age:0,kills:0,made:0,spawn:0,radius:8,paid:false,track:true};G.dirty=true;return true}
function riftTrack(){const e=riftState().encounter;if(e&&e.phase==='dormant'){e.track=true;if(typeof uxAnnounce==='function')uxAnnounce(e.track?'已追蹤斷訊手，角色會沿可達路徑接近。':'停止追蹤斷訊手。')}}
function riftPursuit(){const e=riftState().encounter;if(e?.track&&e.phase==='dormant'&&e.key===terrainKey()){G.h.gx=e.x;G.h.gy=e.y;G.h.aiT=.2;}}
function riftTick(dt){const s=riftState(),e=s.encounter;if(typeof document!=='undefined')document.body.classList.toggle('rift-on',!!e&&['expand','contain'].includes(e.phase)&&!G.offline);if(G.offline)return;if(e&&(e.key!==terrainKey()||G.h.dead>0||G.run||G.train)){s.encounter=null;s.next=60;return}if(!e){if(!G.run&&!G.train&&G.h.dead<=0&&G.depth>=4){s.next-=dt;if(s.next<=0)riftSpawn()}return}if(e.phase==='dormant'){if(Math.hypot(G.h.x-e.x,G.h.y-e.y)<=10){e.phase='expand';e.track=false;e.age=0;SFX('chain');}return}if(e.phase==='complete'||e.phase==='failed'){e.age+=dt;if(e.age>5){s.encounter=null;s.next=90;}return}e.age+=dt;e.radius=e.age<18?8+e.age*1.6:Math.max(8,37-(e.age-18)*.5-e.kills*.35);e.phase=e.age<18?'expand':'contain';e.spawn-=dt;if(e.spawn<=0&&(e.made<72||e.resume>0)&&G.mons.filter(m=>!m.dead&&m.riftId===e.id).length<16&&G.mons.filter(m=>!m.dead).length<hordeCap()+8){e.spawn=.5;const a=e.made*2.399+(Math.random()-.5)*.9,rr=e.radius*(.94+Math.random()*.08),p=terrainProject(e.x+Math.cos(a)*rr,e.y+Math.sin(a)*rr);   /* 沿圈邊緣持續湧出 */const before=G.mons.length;spawnRiftMonster(e,e.made%7===0?'wisp':'skel',...p);const m=G.mons.at(-1);if(G.mons.length>before){m.riftId=e.id;m.hp*=1.2;m.hpMax=m.hp;m.dmg*=1.1;if(e.resume>0)e.resume--;else e.made++;}}if(e.phase==='contain'&&e.kills>=22&&!e.boss)riftBoss(e);const bm=e.boss&&G.mons.find(m=>m.riftBoss&&m.riftId===e.id);if(e.boss&&(!bm||bm.dead))riftFinish(true);else if(e.age>=(e.boss?110:55))riftFinish(false)}
function riftBoss(e){const before=G.mons.length;spawnRiftMonster(e,'boss',...terrainProject(e.x+e.radius*.6,e.y));if(G.mons.length<=before)return;const m=G.mons.at(-1);Object.assign(m,{boss:true,riftBoss:true,riftId:e.id,bossForm:2,fall:.9,rn:'斷訊主宰'});m.hp*=.4;m.hpMax=m.hp;e.boss=true;logLine('裂隙深處的「斷訊主宰」現身了！','#b44bff');if(typeof SFX==='function')SFX('boom')}
function riftOnKill(m){const e=riftState().encounter;if(e&&m.riftId===e.id&&!['complete','failed','dormant'].includes(e.phase)){e.kills++;G.dirty=true;}if(lgOn('R_RIFT')&&(G.riftPulseAt||0)<=G.time){G.riftPulseAt=G.time+1;for(const id of G.slots)G.cds[id]=Math.max(0,(G.cds[id]||0)-.6);}}
function riftFinish(success){const s=riftState(),e=s.encounter;if(!e||e.paid||!['expand','contain'].includes(e.phase))return false;e.paid=true;e.phase=success?'complete':'failed';e.age=0;const amount=success?(e.boss?25:10)+Math.min(10,Math.floor(e.kills/4)):Math.min(5,Math.floor(e.kills/4));if(success)s.clears++;if(amount)dropGround({kind:'rift',amount,x:e.x,y:e.y,t:0});for(const m of G.mons)if(m.riftId===e.id&&!m.dead){m.dead=true;m.deadT=0;deathStain(m);}G.dirty=true;return true}
function riftForge(id){if(!['W_RIFT','R_RIFT'].includes(id)||riftState().shards<40||G.armory[id])return false;const it=makeItem(coreSlot(id),3,Math.max(8,G.maxDepth),id);pickupInternal({kind:'item',it});if(G.armory[id]!==it)return false;riftState().shards-=40;G.dirty=true;saveGame();return true}
/* Radius follows rendered body size, never a fixed boss-only bucket. No RNG here. */
function deathStainRadius(m){
 const actual=typeof monsterVisualSpan==='function'?monsterVisualSpan(m):0;
 const trait=typeof MONSTER_TRAITS!=='undefined'?MONSTER_TRAITS[m.type]:null;
 const fallback=(m.boss||m.towerBoss?42:trait?.size==='大型'?24:trait?.size==='中型'?15:10)*(trait?.scale||1)*(m.elite?1.3:1);
 return Math.max(.75,(actual>0&&Number.isFinite(actual)?actual:fallback)*.26);
}
const STAIN_LIFE=90,STAIN_MAX=40;
function deathStain(m){if(G.offline||m.training||typeof deathFxStyle==='function'&&deathFxStyle()==='none')return;G.stains=G.stains||[];const r=deathStainRadius(m),blobs=[],n=m.boss?7:5;for(let i=0;i<n;i++){const a=Math.random()*6.283,d=i?r*(.25+Math.random()*.55):0;blobs.push({dx:Math.cos(a)*d,dy:Math.sin(a)*d,r:r*(i?.32+Math.random()*.38:.62+Math.random()*.15)});}
 const drops=m.boss?5:3;for(let i=0;i<drops;i++){const a=Math.random()*6.283,d=r*(1.15+Math.random()*.7);blobs.push({dx:Math.cos(a)*d,dy:Math.sin(a)*d,r:r*(.09+Math.random()*.1),drop:1});}
 G.stains.push({x:m.x,y:m.y,t:0,r,blobs,key:terrainKey()});if(G.stains.length>STAIN_MAX)G.stains.shift()}
function deathVisualTick(dt){for(const e of G.fx)e.t+=dt/e.dur;G.fx=G.fx.filter(e=>e.t<1);for(const f of G.floats)f.t+=dt/1.1;G.floats=G.floats.filter(f=>f.t<1);for(const m of G.mons)if(m.dead)m.deadT=(Number.isFinite(m.deadT)?m.deadT:0)+dt;G.mons=G.mons.filter(m=>!m.dead||m.deadT<.6);G.stains=(G.stains||[]).filter(s=>{s.t+=dt;return s.t<STAIN_LIFE&&s.key===terrainKey()})}

function spawnRiftMonster(e,type,x,y){const T=MTYPES[type],d=lvlNow(),hp=24*Math.pow(1.32,d-1)*T.hp*HORDE.hp;let slot=0;const used=new Set(G.mons.filter(m=>!m.dead).map(m=>m.slot));while(used.has(slot)&&slot<SLOTS.length-1)slot++;G.mons.push({type,x,y,hp,hpMax:hp,dmg:4.5*Math.pow(1.22,d-1)*T.dmg*HORDE.dmg,atkInt:T.atk,spdK:1,atkCd:1,skillCd:3,slot,fall:0,fight:false,dead:false,deadT:0,hurtT:0,frozen:0,lunge:-1,lungeHit:true,ph:Math.random()*6,boss:false,elite:false});}

