/* First-session guidance records real actions, never equips or wires for the player. */
function onboardingClean(o){if(!o||o.v!==1)return null;return{v:1,active:o.active===true,done:o.done===true,stage:Math.max(0,Math.min(3,Math.floor(o.stage)||0)),startKills:Math.max(0,Math.floor(o.startKills)||0),equipped:o.equipped===true,giftClaimed:o.giftClaimed===true,giftEligible:o.giftEligible===true};}
function onboardingStart(newCharacter=false){if(!G.tutorial||G.tutorial.done)G.tutorial={v:1,active:true,done:false,stage:0,startKills:G.totalKills,equipped:false,giftClaimed:false,giftEligible:newCharacter&&G.lvl<6&&G.totalKills<20};else G.tutorial.active=true;G.dirty=true;}
function onboardingEvent(kind){const t=G.tutorial;if(!t||t.done)return;if(kind==='equip'){t.equipped=true;G.dirty=true;}}
function onboardingTick(){const t=G.tutorial;if(!t?.active||t.done||G.offline||G.paused)return false;const before=t.stage;if(t.stage===0&&G.totalKills-t.startKills>=3){t.stage=1;if(!t.giftClaimed){t.giftClaimed=true;if(t.giftEligible&&!G.inventory.some(it=>G.equip[it.slot]!==it)){const it=makeItem('weapon',1,2);it.name='校準訊號棒';it.aff=[{k:'dmg',v:4}];dropGround({kind:'item',it,x:G.h.x,y:G.h.y,t:0});}}}if(t.stage===1&&t.equipped)t.stage=2;if(t.stage===2&&GridLab.resolve(G.board,G.lvl).some(r=>r.wired))t.stage=3;if(before!==t.stage){G.dirty=true;saveGame();return true;}return false;}
function onboardingPause(){if(!G.tutorial)return;G.tutorial.active=false;G.dirty=true;saveGame();}
function onboardingFinish(){if(!G.tutorial||G.tutorial.stage!==3)return false;G.tutorial.done=true;G.tutorial.active=false;G.dirty=true;saveGame();return true;}

